        {"원어":"σκοτία (스코티아)", "의미_문법":"어두움 - 명사 여성 단수. 영적 어둠·죄", "설교포인트":"하나님을 떠난 인류의 영적 상태를 나타냄"},
        {"원어":"κατέλαβεν (카텔라벤)", "의미_문법":"깨닫지 못하다/이기지 못하다 - 동사 아오리스트. 이중적 의미: 이해·정복", "설교포인트":"어둠이 빛을 이해하지도 이기지도 못함"}
