        {"항목":"요한복음의 전환점", "내용":"10-11절의 거부 후 12절은 극적인 전환. 거부의 어둠 속에서 은혜의 빛이 터져 나옴. 이 구절은 요한복음 서론의 복음적 절정", "목회적활용":"가장 어두운 시점에서 가장 밝은 복음이 선포됨"}
