        {"항목":"세 가지 부정의 구조", "내용":"혈통(αἱμάτων) → 육정(σαρκός) → 사람의 뜻(ἀνδρός)은 점점 범위를 좁혀가는 구조. 민족적 → 본능적 → 의지적 차원 모두를 부정", "목회적활용":"인간의 어떤 노력이나 조건도 거듭남의 원인이 될 수 없음을 완전히 선언"},
        {"항목":"영지주의 대항", "내용":"영지주의는 특별한 지식(그노시스)을 가진 자만 구원받는다고 주장. 요한은 인간의 어떤 능력이 아닌 오직 하나님의 역사로 구원이 이루어짐을 선언", "목회적활용":"구원은 인간의 지식이나 능력이 아닌 전적인 하나님의 은혜"}
