        {"새찬송가":"430", "통일찬송가":"365", "제목":"겸손히 주를 섬기며", "선정이유":"요한의 겸손한 증거자 자세"},
        {"새찬송가":"76", "통일찬송가":"76", "제목":"기뻐하며 경배하세", "선정이유":"영원 전부터 계신 분에 대한 경배"},
        {"새찬송가":"8", "통일찬송가":"8", "제목":"전능왕 오셔서", "선정이유":"영원하신 전능왕의 오심"}
