        {"상황":"한 번의 은혜 체험 후 신앙이 정체된 분", "성경원리":"'은혜 위에 은혜'는 계속적 은혜의 연쇄. 구원의 은혜는 시작일 뿐 끊임없이 새로운 은혜가 이어짐", "실제적용":"과거의 체험에 머물지 말고 오늘의 새로운 은혜를 기대하라. 매일이 은혜의 새 페이지"}
