    표5_매튜헨리: [
        {"영어원문":"No man hath seen God at any time. The nature of God being spiritual, he is invisible to bodily eyes.", "한국어번역":"어느 때에도 하나님을 본 사람이 없으니 하나님의 본성이 영이시므로 육체의 눈에 보이지 않으신다.", "핵심통찰":"하나님의 영적 본성은 인간의 감각으로 접근 불가"},
        {"영어원문":"The only begotten Son, which is in the bosom of the Father, he hath declared him.", "한국어번역":"아버지 품속에 있는 독생자가 그를 나타내셨다.", "핵심통찰":"가장 친밀한 관계에 있는 아들만이 아버지를 완전히 계시"},
        {"영어원문":"He hath declared him — made him known in a way that was never done before.", "한국어번역":"그가 나타내셨으니 이전에는 결코 이루어지지 않았던 방식으로 하나님을 알게 하셨다.", "핵심통찰":"그리스도의 계시는 전무후무한 하나님의 자기 나타내심"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"보이지 않는 하나님을 보여주신 독생자 — 요한복음 서론의 결론", "예화_적용":"커튼 뒤에 숨겨진 보물을 열어 보여주신 분이 예수 그리스도"},
        {"대지":"서론", "내용":"18절은 요한복음 서론(1-18절)의 마지막 절이자 절정이다. 1절에서 '말씀은 하나님이시다'로 시작하여 18절에서 '독생하신 하나님이 나타내셨다'로 마무리한다. 서론 전체가 하나의 질문에 답한다 — 보이지 않는 하나님을 어떻게 알 수 있는가", "예화_적용":"어둠 속에서 길을 잃었을 때 누군가 손전등을 켜준다면 — 그리스도가 바로 그 빛"},
        {"대지":"1대지: 본래 하나님을 본 사람이 없으되 (인간의 한계)", "내용":"어떤 인간도, 모세도, 이사야도, 아브라함도 하나님의 본질을 직접 본 적이 없다. 이것은 인간의 근본적 한계", "예화_적용":"아무리 좋은 망원경으로도 우주의 끝을 볼 수 없듯 인간의 능력으로는 하나님을 볼 수 없다"},
        {"대지":"2대지: 아버지 품속에 있는 독생하신 하나님 (유일한 자격)", "내용":"아버지의 '품속'(콜폰)은 가장 친밀한 위치. 이 위치에 있는 분만이 아버지를 완전히 안다. 그리고 이 분은 '하나님'이시다", "예화_적용":"아버지의 비밀을 아는 것은 아버지 품에 안긴 자녀뿐이다"},
        {"대지":"3대지: 나타내셨느니라 (완전한 계시)", "내용":"'엑세게사토'는 해석하다. 그리스도가 보이지 않는 하나님을 세상에 '해석'해 주셨다. 예수를 보면 하나님을 본다(요 14:9)", "예화_적용":"외국어 책을 읽을 수 없을 때 번역가가 필요하듯 하나님을 알기 위해 그리스도가 필요하다"},
        {"대지":"결론", "내용":"하나님을 알고 싶으면 예수를 보라. 하나님을 만나고 싶으면 예수에게 나아가라. 그가 보이지 않는 하나님을 보여주신 유일한 분이시다", "예화_적용":"예수님이 빌립에게 말씀하셨다 — 나를 본 자는 아버지를 보았거늘(요 14:9)"}
    ],
